import java.util.*;

class Node {
    public int val;
    public Node left, right, next;

    public Node(int v) { val = v; }
}

class Solution {
    public Node connect(Node root) {
        if (root == null) return null;
        Node cur = root;
        while (cur.left != null) {
            Node head = cur;
            while (head != null) {
                head.left.next = head.right;
                if (head.next != null) head.right.next = head.next.left;
                head = head.next;
            }
            cur = cur.left;
        }
        return root;
    }
}

