        return t.split("\\s+");
    }

    static Node buildNode(String[] a) {
        if (a.length == 0 || a[0].equals("null")) return null;
        Node root = new Node(Integer.parseInt(a[0]));
        List<Node> q = new ArrayList<>();
        q.add(root);
        int head = 0, i = 1;
        while (head < q.size() && i < a.length) {
            Node node = q.get(head++);
            if (i < a.length) {
                if (!a[i].equals("null")) {
                    node.left = new Node(Integer.parseInt(a[i]));
                    q.add(node.left);
                }
                i++;
            }
            if (i < a.length) {
                if (!a[i].equals("null")) {
                    node.right = new Node(Integer.parseInt(a[i]));
                    q.add(node.right);
                }
                i++;
            }
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        List<String> ls = lines();
        Node root = buildNode(tokens(String.join(" ", ls)));
        Node cur = root;
        while (cur != null && cur.left != null) {
            Node head = cur;
            while (head != null) {
                head.left.next = head.right;
                if (head.next != null) head.right.next = head.next.left;
                head = head.next;
            }
            cur = cur.left;
        }
        StringBuilder out = new StringBuilder();
        List<Node> q = new ArrayList<>();
        if (root != null) q.add(root);
        while (!q.isEmpty()) {
            List<Node> nxt = new ArrayList<>();
            for (Node n : q) {
                out.append(n.val).append(',');
                if (n.left != null) nxt.add(n.left);
                if (n.right != null) nxt.add(n.right);
            }
            out.append("#,");
            q = nxt;
        }
        if (out.length() == 0) {
            System.out.println("[]");
        } else {
            out.setLength(out.length() - 1);
            System.out.println("[" + out + "]");
