    TreeNode(int v) { val = v; }
}

class Solution {
    private int ans = Integer.MAX_VALUE;
    private Integer pre = null;

    public int getMinimumDifference(TreeNode root) {
        dfs(root);
        return ans;
    }

    private void dfs(TreeNode node) {
        if (node == null) return;
        dfs(node.left);
        if (pre != null) ans = Math.min(ans, node.val - pre);
        pre = node.val;
        dfs(node.right);
    }
