import java.util.*;

class Solution {
    private Set<Integer> cols = new HashSet<>();
    private Set<Integer> diag1 = new HashSet<>();
    private Set<Integer> diag2 = new HashSet<>();

    public int totalNQueens(int n) {
        return dfs(n, 0);
    }

    private int dfs(int n, int r) {
        if (r == n) return 1;
        int cnt = 0;
        for (int c = 0; c < n; c++) {
            if (cols.contains(c) || diag1.contains(r - c) || diag2.contains(r + c)) continue;
            cols.add(c);
            diag1.add(r - c);
            diag2.add(r + c);
            cnt += dfs(n, r + 1);
            cols.remove(c);
            diag1.remove(r - c);
            diag2.remove(r + c);
        }
        return cnt;
    }
}

